      "title": "About Larkspur Supply Co.",
      "site": "Larkspur Supply Co.",
      "description": "About Larkspur Supply Co.: our story, what we believe, and our milestones.",
      "heading": "About Larkspur Supply Co."
    },
    "slots": {
      "main": [
        {
          "use": "content/section",
          "key": "story",
          "data": { "title": "Our story" },
          "slots": {
            "body": [
              {
                "use": "content/prose",
                "key": "story-text",
                "data": { "html": "<p>Twelve paddlers and climbers founded the co-op in 1987 in a rented garage. Today 9,400 members own it, and every member gets one vote at the annual meeting.</p>" }
              }
            ]
          }
        },
        {
          "use": "content/section",
          "key": "beliefs",
          "data": { "title": "What we believe" },
          "slots": {
            "body": [
              {
                "use": "content/prose",
                "key": "beliefs-list",
                "data": { "html": "<ol><li>Repair before replace. Our workshop fixed 3,100 items last year.</li><li>Pay people fairly. Every employee earns at least the regional living wage.</li><li>Leave places better. We give 2% of sales to trail and shoreline groups.</li></ol>" }
              }
            ]
          }
        },
        {
          "use": "content/section",
          "key": "milestones",
          "data": { "title": "Milestones" },
          "slots": {
            "body": [
              {
                "use": "data/description-list",
                "key": "milestone-list",
                "data": {
                  "items": [
                    { "term": "1987", "description": "Founded in a garage on Pier Road." },
                    { "term": "1999", "description": "Opened the Alder Street store." },
                    { "term": "2014", "description": "Started the rental program." },
                    { "term": "2023", "description": "Opened the repair workshop." }
                  ]
                }
              }
            ]
          }
        },
        {
          "use": "content/quote",
          "key": "chair-quote",
          "data": {
            "quote": "We are not here to sell more gear. We are here to help people get outside with the gear they already have.",
            "author": "Ines Okafor",
            "source": "Board chair"
          }
        },
        {
          "use": "content/prose",
          "key": "links",
          "data": { "html": "<p><a href=\"/reports/2025.pdf\">Read the annual report</a></p><p><a href=\"/team\">Meet the team</a></p>" }
        }
      ]
    }
  }
}
